#include <stdio.h>
#include <string.h>

#define MAXLEN 64
#define DP_SIZE (MAXLEN + 1)

static int main_dp[DP_SIZE][DP_SIZE];

int main(int argc, char *argv[])
{
    if (argc < 3) {
        puts("USAGE");
        return 0;
    }
    const char *s1 = argv[1];
    const char *s2 = argv[2];
    size_t len1 = strlen(s1);
    size_t len2 = strlen(s2);
    if (len1 > MAXLEN || len2 > MAXLEN) {
        puts("TOO_LONG");
        return 0;
    }
    for (size_t i = 0; i <= len1; ++i)
        main_dp[i][0] = (int)i;
    for (size_t j = 0; j <= len2; ++j)
        main_dp[0][j] = (int)j;
    for (size_t i = 1; i <= len1; ++i) {
        for (size_t j = 1; j <= len2; ++j) {
            int cost = (s1[i-1] == s2[j-1]) ? 0 : 1;
            int deletion = main_dp[i-1][j] + 1;
            int insertion = main_dp[i][j-1] + 1;
            int substitution = main_dp[i-1][j-1] + cost;
            int best = deletion;
            if (insertion < best) best = insertion;
            if (substitution < best) best = substitution;
            main_dp[i][j] = best;
        }
    }
    printf("%d\n", main_dp[len1][len2]);
    return 0;
}
